pub assume_specification<T, A: Allocator>[
    VecDeque::<T, A>::capacity
](v: &VecDeque<T, A>) -> (capacity: usize)
    ensures
        v@.len() <= capacity as int,
;

pub assume_specification<T, A: Allocator>[
    VecDeque::<T, A>::reserve_exact
](
    v: &mut VecDeque<T, A>,
    additional: usize,
)
    ensures
        final(v)@ == old(v)@,
;

pub assume_specification<T, A: Allocator>[
    VecDeque::<T, A>::shrink_to
](
    v: &mut VecDeque<T, A>,
    min_capacity: usize,
)
    ensures
        final(v)@ == old(v)@,
;

pub assume_specification<T, A: Allocator>[
    VecDeque::<T, A>::shrink_to_fit
](v: &mut VecDeque<T, A>)
    ensures
        final(v)@ == old(v)@,
;
